insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('f531741e-c835-53f7-a533-bd0e9bab2b9d','do-caos-flash-ao-tedio-flat','article','Do caos { flash } ao tédio { flat }','Eu comecei a desenvolver front-end em 2009. Naquela época, era um desafio entregar sites bonitos, funcionais e que funcionassem bem em vários navegadores. Muita…','Código','<p>Eu comecei a desenvolver front-end em 2009. Naquela época, era um desafio entregar sites bonitos, funcionais e que funcionassem bem em vários navegadores.</p><p>Muita gente não faz ideia do quão trabalhoso era usar um simples PNG.</p><p>O suporte ao CSS era precário, o JavaScript era interpretado de formas diferentes, e até tags HTML básicas levavam anos para ter suporte nos navegadores.</p><p>Às vezes, centralizar uma &lt;div&gt; era um verdadeiro desafio.</p><p>Além disso, ainda lidávamos com conexões de internet extremamente lentas.</p><p>Hoje, mesmo com a evolução constante do CSS, dos frameworks modernos de JavaScript, da inteligência artificial e da velocidade da internet, sinto que no design não acompanhamos essa evolução — e talvez até tenhamos regredido.</p><p>Ícones estão cada vez mais genéricos, sem personalidade; as fontes são as mesmas de 15 anos atrás; e os sites, cada vez mais padronizados, estáticos e menos interativos.</p><p>Não quero voltar ao espetáculo dos sites em Flash, mas se antes eu precisava conversar com designers sobre as limitações do que estávamos construindo, hoje preciso convencer que podemos e devemos explorar mais: elementos interativos, animações, transições e a barra de scroll.</p><p>Hoje não precisamos mais perder tempo com CSS sprites, converter fontes em imagens, usar GIF de 1px pra empurrar layout ou fazer gambiarras pra suportar tags que alguns navegadores nem reconheciam.</p><p>A internet voa, o suporte é amplo, as ferramentas são poderosas.</p><p>E mesmo assim… seguimos escolhendo ícones estáticos de bibliotecas prontas como se fosse o auge da criatividade. Pelo amor de Deus — dá pra fazer mais, muito mais.</p>','published','2025-05-26T18:16:22.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/do-caos-flash-ao-t%C3%A9dio-flat-027fe7a61221',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('ccae7b69-1a23-5865-aa10-a2be608d57db','penar','article','Penar','Há um lugar para onde meus pensamentos sempre voltam. Minha memória floresce sempre que lembro da terra vermelha, das árvores retorcidas e do rio que lá margeia:…','Vida','<p>Há um lugar para onde meus pensamentos sempre voltam. Minha memória floresce sempre que lembro da terra vermelha, das árvores retorcidas e do rio que lá margeia: Paraopeba.</p><p>Cavalguei ao encontro de suas águas centenas de vezes, montando em Torresmo ou Tornado, meus cavalos, puxado na charrete pela mula Florinha, ou caminhando com amigos, sempre acompanhado pelos meus cachorros.</p><p>Ali, na margem, encontrei consolo e confronto.</p><p>Chupei mexerica, tomei vinho, e enquanto o rio seguia seu curso, perdi a conta das vezes que ele refletiu mais do que meu rosto — refletiu o que eu sentia, o que eu temia. Às vezes, eu sentia que suas águas aliviavam o que me pesava, como se enterrassem na lama os segredos que só ele sabia.</p><p>Foi lá que aprendi que o homem precisa ser forte. Para enfrentar a seca, não basta ter bons pensamentos; é o corpo que fortalece o espírito. É suportar o frio do amanhecer e o sol escaldante no corpo do dia. É levantar a vaca enfraquecida, erguer a pacetta e jogá-la contra a terra ressequida. No cerrado, força não é virtude — é necessidade.</p><p>Mesmo depois de ter partido, algo lá — o cerrado, o rio, sei lá — ainda me imanta sem que eu entenda. Às vezes, perco o sono; às vezes, sonho. Às vezes, quero esquecer das obrigações, da minha profissão, das paixões. De algum jeito, algo continua a me puxar para aquele lugar.</p><p>Saí de lá não porque quisesse, mas porque precisava. Eu amava aquele lugar de um jeito que me consumia, era um peso, um fardo que, em algum momento, me tornou insustentável.</p><p>Partir não significou encontrar a solução, mas talvez o único caminho que me restava. A saudade não me faz mais forte. O que deixou em mim é essa necessidade de recomeçar, de aprender a viver fora daquilo que era meu mundo, e ao mesmo tempo, me questionar o que realmente me segurava lá.</p><p>Sinto-me agora condenado a uma existência dividida, onde, em algum canto de mim, ainda estou lá. Algo ficou preso nas margens daquele rio. E agora, onde quer que eu vá, sou como uma alma que ainda vaga, a penar entre o que perdi e a dor de não poder voltar. Ao deixar o lugar que tanto amei, tornei-me, sem querer, uma alma a penar — entre o que fui e o que sou. Angueretá.</p>','published','2025-01-23T13:22:41.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/penar-8da5e3640ba1',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('9f778b5a-0767-54b4-a671-c2349a807e0e','por-um-2023-mais-textual','article','Por um 2023 mais textual','Eu gosto de escrever, sempre gostei. Tenho um desejo tímido de um dia escrever um livro. Não quero ser como Tolstói, Guimarães Rosa e Mia Couto. Só queria escrever…','Vida','<p>Eu gosto de escrever, sempre gostei. Tenho um desejo tímido de um dia escrever um livro. Não quero ser como Tolstói, Guimarães Rosa e Mia Couto. Só queria escrever um livro que provocasse algumas risadas.</p><p><strong>É um objetivo pra 2023: escrever mais!</strong></p><p>Sem compromisso, apenas pelo prazer, pela prática, pra expor e escoar pensamentos. Talvez de forma mais generalizada. Dá pra abordar muitos assuntos de forma suscinta dentro de um mesmo texto. Não precisa ter muita lógica também. Não sou intelectual! Não preciso dissecar um assunto e também não tenho compromisso com intelectual com ninguém e o português pode ser informal. Dá nada pra nós!</p><p>Também usar expressões que estão no meu vocabulário diariamente. Temos que ficar presos na formalidade do português pra escrever?</p><p>Eu uso redes sociais pra registrar alguns momentos da minha vida. Gosto de registrar os primeiros passos de uma atividade e criar um histórico de evolução. Como quando a gente pega um cavalo pra domar, gosto de ver o processo de transformação. Por quê não fazer isso com meus pensamentos? O que eu estava pensando no dia xx/xx quando falei com minha amiga que estava interessado nela? Eu não sei, não escrevi! (E isso pode render boas risadas!) O que eu pensava antes e penso agora é um processo. Não quero lembrar apenas das repostas.</p><p>Por algum motivo eu sempre considerei que deveria registrar só pensamentos já bem estabelecidos.</p><blockquote>“Jogo fora as certezas, o que sobra é só coragem…”<br>Norte — Ponto Nulo no Céu.</blockquote><p>Eu só quero escrever. Quero dar vazão ao que estou pensando. Não sei quem vai se interessar e tanto faz.</p><p>Nesse ano eu quero coragem pra viver novas experiências e vou tentar registrar textualmente alguns momentos.</p><p>Feliz 2023!</p>','published','2023-01-02T12:06:13.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/por-um-2023-mais-textual-7cced097729c',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('0270ddcf-29ad-56f8-ab1e-5d69073d161b','na-linha-de-frente-retomei-minha-profissao','article','Na linha de frente: retomei minha profissão.','Treze anos que estou desenvolvendo pra web ocupando o cargo de Front-end Developer. São treze anos escrevendo HTML, CSS e JavaScript. Eu comecei a estudar em 2008.…','Código','<p>Treze anos que estou desenvolvendo pra web ocupando o cargo de Front-end Developer. São treze anos escrevendo HTML, CSS e JavaScript.</p><p>Eu comecei a estudar em 2008. E eu estudei pra um caralho naquela época. Noites e noites sem dormir e geral falando que eu não sabia o que estava fazendo. Eu morava em Ipatinga, não tinha muita oportunidade pra trabalho lá na época.</p><p>Nunca pisei numa faculdade. Eu sequer fiz o ensino fundamental completo (assunto pra um outro post, mas pulei da sexta pra oitava no meio do ano 😂). Na maioria das empresas eu era o único sem formação superior e, modéstia a parte, nunca fiquei pra trás de ninguém. Tenho zero demissões. Todas as empresas que trabalhei me procuraram pra prestar serviços em algum momento.</p><p>É um post de auto elogio sim. Porque isso que eu fiz foi foda pra caralho. Foi subversivo. Eu tenho um puta orgulho disso!</p><p>Voltei pro mercado de trabalho tem um mês (fiquei sete anos fora). Mesmo com toda experiência dei uns passos atrás pra conseguir novamente ser o desenvolvedor que sempre fui.</p><p>Me bastava uma única experiência na área de tecnologia, mas eu consegui muito mais.</p><p>Hoje, treze anos depois, acho que consegui o equilíbrio. Trabalho remoto. Posso morar aonde quiser. Se concretizou tudo que eu desejava lá no início. Eu tive que mudar de cidade duas vezes. Eu simplesmente odivava morar em Belo Horizonte. Odiei quando tive que sair de Ipatinga pra Uberlândia.</p><p>Eu gostava do meu trabalho, mas não suportava viver na cidade grande. Larguei mão pra ir pra roça consciente que com o tempo eu perderia profissionalmente.</p><p>Eu poderia sim estar numa posição melhor se apenas tivesse seguido minha carreira.</p><p>Mas eu sempre quis ter uma vida além da profissão. Quebrar aquela rotina de casa-trabalho.</p><blockquote>Um homem precisa muito mais do que apenas saber ganhar dinheiro.</blockquote><p>Se eu perdi profissionalmente enquanto estive fora do mercado eu ganhei mil vezes mais em habilidades manuais, conhecimento pessoal, tive muitas experiências reais e aprendi a viver no mundo.</p><p>Minha profissão está em alta hoje. Tem vaga pra todo tipo de gente. Saio na rua aqui na roça falando pra qualquer um &quot;aprende a programar, é só estudar...&quot;. Sabe quantos eu já consegui convencer? Nenhum! Ter que passar a vida profissional inteira se atualizando não é fácil. Mas por tudo que aconteceu até aqui a escolha da profissão foi a melhor que fiz na vida.</p>','published','2022-09-13T22:59:37.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/na-linha-de-frente-retomei-minha-profiss%C3%A3o-de6fbd7b85c2',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('4123ddea-099d-551d-a5cd-185f6e15087f','feijao-arroz','article','Feijão-arroz (Vigna Umbellata).','Quatro anos atrás eu encontrei sementes desse feijão aqui no quintal. Guardei e esqueci. Ano passado eu lembrei e decidi pesquisar sobre. Me pareceu uma espécie…','Roça','<figure><img alt="" src="https://cdn-images-1.medium.com/max/720/1*5pz_VQ59Y1lZcFSzbUCMFA.jpeg" /></figure><p>Quatro anos atrás eu encontrei sementes desse feijão aqui no quintal. Guardei e esqueci. Ano passado eu lembrei e decidi pesquisar sobre. Me pareceu uma espécie muito produtiva e resistente. Plantei as poucas sementes que tinha guardado e apenas três brotaram.</p><p>Em breve vou colher as sementes experimentar e guardar pro próximo ano. Se o sabor não for bom pode ser usado pra adubação verde.</p><p>Nesse processo de resgate serão dois anos pra conseguir quantidade suficiente pra adicionar nas refeições.</p><p>Aqui estou produzindo cinco espécies de feijões. Guandu, duas espécies de fava, feijão-de-corda e feijão-arroz. Todos são produtivos, nascem espontaneamente e são de fato orgânicos.</p><p>Obs: colhi 2kg e o sabor é muito bom.</p>','published','2020-10-13T16:35:20.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/feij%C3%A3o-arroz-vigna-umbellata-ec94e5cd3d59',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('4d81ed5c-2653-5483-a1e8-c39e428ef8f4','tratando-do-gado','article','Eu estava tratando do gado e pensei "não tenho foto fazendo isso".','Eu estava tratando do gado e pensei &quot;não tenho foto fazendo isso&quot;. Tirei esse trem aí pra registrar. Outro dia eu estava contando para meus vizinhos que…','Roça','<figure><img alt="" src="https://cdn-images-1.medium.com/max/1024/1*42mPFrGabGlta898H6dVLw.jpeg" /></figure><p>Eu estava tratando do gado e pensei &quot;não tenho foto fazendo isso&quot;. Tirei esse trem aí pra registrar.</p><p>Outro dia eu estava contando para meus vizinhos que já tive piercing, alargador, usei moicano, andava com umas roupas rasgadas, andei de skate e toquei em banda (isso tudo na adolescência). As pessoas que me conhecem hoje ficam incrédulas quando conto essas coisas, as que me conheciam amtes não acreditam no que faço hoje.</p><p>O futuro a Deus pertence, mas hoje esse aí é o André. O cara que mudou da cidade pra roça. Deixou de ser programador pra servir gado e limpar curral. Se serei assim pra sempre eu não sei.</p><p>Eu sempre caminhei em sentido a liberdade. As vezes tenho que fazer desvios, mas um dia eu chego lá.</p><p>Viver a vida é mais do que sobreviver. Quero colecionar histórias e experiências.</p>','published','2020-10-13T16:27:51.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/eu-estava-tratando-do-gado-e-pensei-n%C3%A3o-tenho-foto-fazendo-isso-fc65761ba2f2',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('43ffed49-58e4-5ba7-aebb-badce16710f2','dez-anos-atras-eu-morava-em-ipatinga','article','Dez anos atrás eu morava em Ipatinga.','Dez anos atrás eu morava em Ipatinga. Virava noite estudando padrões web, HTML, CSS e JavaScript. Minha família estava fodida de grana e eu precisava arrumar um…','Roça','<p>Dez anos atrás eu morava em Ipatinga. Virava noite estudando padrões web, HTML, CSS e JavaScript. Minha família estava fodida de grana e eu precisava arrumar um emprego. Consegui, mas foi lá em Uberlândia. Fui pra lá. Depois de um tempo levei minha mãe. Trabalhei igual um condenado, adquiri experiência e aprendi minha profissão.</p><p>No início do ano eu participava de uma igreja, gostava da minha cidade, teologia, hardcore, tinha um punhado de amigos e andava de bicicleta pra cima e pra baixo e no meio daquele ano eu larguei tudo.</p><p>Eu consegui meu primeiro emprego de carteira assinada e foi muito bom na época.</p><p>Agora eu estou morando em Angueretá. Tirando leite, fazendo queijo, criando galinha, capinando e desenvolvendo habilidades braçais. Virei um fazendeiro descapitalizado. Ainda pego uns freelas quando aparece (inclusive #mandajobs).</p><p>Putz, muita coisa mudou em 10 anos. Engordei pra cacete depois que comecei a tomar açaí em Uberlândia (era muito bom). Casei. Mudei de cidade 3 vezes. Arrumei uns cachorros. Troquei de emprego algumas vezes...</p><p>Sabe o que não mudou? Eu ainda estou fodido de grana.rs Mas está tudo bem. Acumular dinheiro nunca foi objetivo.</p><p>O objetivo pra 2019 é o mesmo de sempre: SOBREVIVER. Sentir o vento, observar as estações, esperar a chuva (e reclamar do sol), plantar, colher, fazer de tudo um pouco, me afastar dos boletos e viver cada vez mais livre.</p>','published','2019-01-21T04:03:59.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/dez-anos-atr%C3%A1s-eu-morava-em-ipatinga-8fd78145cef9',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('70721c9b-df7f-5fa9-ad76-eb32b650f6a4','causo-da-abelha','article','Causo da abelha','Estava plantando feijão guandu quando, de repente, uma abelha começou a sobrevoar meu rosto. Com certeza não era uma boa abelha. Ela estava sozinha. Você já viu uma…','Roça','<p>Estava plantando feijão guandu quando, de repente, uma abelha começou a sobrevoar meu rosto.</p><p>Com certeza não era uma boa abelha. Ela estava sozinha. Você já viu uma abelha sozinha? Esse não era um bom sinal, mas eu não soube interpretar.</p><p>Nos últimos dias, eu corri de no mínimo 5 bandos de marimbondos, que foram golpeados acidentalmente enquanto eu roçava o pasto. Apenas uma vez fui pego. E com certeza não foi apenas um soldado que me atacou.</p><p>Por estar sozinha, pensei que ela estava rondando a área de forma despretensiosa e sem maldade.</p><p>Eu aprendi que não podemos matar uma abelha porquê elas liberam um cheiro que atrai outras abelhas vingativas. Sem contar que nós precisamos das abelhas e seria péssimo matar um exemplar dessa raridade.</p><p>Mas antes eu tivesse estapeado ela e pisado em cima...</p><p>Ela sobrevoou a minha cabeça e eu pensei &quot;já vai tarde, demonha&quot;, porém numa reviravolta surpreendente a danada acertou um golpe certeiro no meu nariz. Antes mesmo de sentir a dor, por algum motivo, meus olhos começaram a lacrimejar e então eu saí correndo com cara de choro e enxada na mão estapeando o ar. Por sorte eu consegui salvar minha orelha de um novo golpe.</p><p>Ela ainda me perseguiu por uns 20 metros em alta velocidade. Eu sei que elas vigiam as colméias e atacam para se proteger. Mas eu não fiz nada e com certeza não estava perto suficiente de uma colméia.</p><p>Conclui que era uma abelha má, simples assim.</p>','published','2017-11-25T00:13:46.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/causo-da-abelha-5d2170ed4e5a',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('6e94838a-bfb2-5e89-abca-21641b5cc0f8','causo-do-rato','article','Causo do rato','Hoje pela primeira vez eu vi um ratinho no telhado da casa. Fui correndo e peguei minha zarabatana. Alvo na mira, soprei… Errei por pouco e o bicho se escondeu.…','Roça','<figure><img alt="" src="https://cdn-images-1.medium.com/max/640/1*fgFa5j_ePzqW7jY226W0Lw.jpeg" /></figure><p>Hoje pela primeira vez eu vi um ratinho no telhado da casa.</p><p>Fui correndo e peguei minha zarabatana. Alvo na mira, soprei… Errei por pouco e o bicho se escondeu.</p><p>Sentei e pensei “e agora? fodeu”.</p><p>Depois de uma hora mais ou menos minha esposa viu o bicho passando na direção oposta. Ela me chamou e já passei a mão na zarabatana. Pensei: <strong><em>“Dessa vez esse demonho não escapa”</em></strong>; antes mesmo de ver o bicho ele já estava lá fora.</p><blockquote>“Lálálá ninguém me pega, seus trouxa”, pensou o ratinho.</blockquote><p>Antes do ratinho terminar seu pensamento nós escutamos umas telhas se mexendo… Corremos lá pra fora, subimos na torre e olhamos no telhado. Era o gato.</p><p>Acho que o gato Bolou a emboscada sozinho e sem falar nada esperou pela nossa participação pra garantir.</p><p><strong>Esses bichos são “<em>veiacos</em>” demais.</strong></p><p>E o dia foi salvo por um de nossos gatos pretos sem nome.</p>','published','2017-11-21T15:43:00.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/causo-do-rato-3bac6c4ddb34',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('3161f5cc-3b04-5a92-a16f-9ad1f6fd49c7','um-ano-e-meio-de-roca','article','Um ano e meio de roça','Antes de mudar pra roça eu tinha medo do tédio. Mas depois que pega ritmo o tédio não existe. Só naqueles dias que seu corpo não aguenta mais se mexer e você tem…','Roça','<p>Antes de mudar pra roça eu tinha medo do tédio.</p><p>Mas depois que pega ritmo o tédio não existe. Só naqueles dias que seu corpo não aguenta mais se mexer e você tem que parar pra recuperar energias.</p><p>Um ano e meio morando aqui e sempre estou fazendo algo novo. Graças a Deus.</p><p>Oração do dia:<br>Que Deus continue me livrando do trânsito, da rotina e do patrão.<br> Amém.</p><figure><img alt="" src="https://cdn-images-1.medium.com/max/16/0*Avw9wGuTEoQGcsW_.png" /></figure>','published','2017-11-21T15:22:33.000Z','[]',null,null,null,'https://medium.com/@andre_amaral/um-ano-e-meio-de-ro%C3%A7a-a98e2d615241',null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('508344c6-8c06-5b1d-a966-bcb737a71283','caminhos-do-cerrado','story','Caminhos do cerrado','O cavalo, a companhia e o caminho de volta.','Roça','<p>O cerrado, seus frutos, o cheiro, o brilho, o rio, a simplicidade. Um lugar que continua comigo.</p>','published',now(),'[{"url":"/images/caminho-cerrado.jpeg","caption":"A companhia no caminho.","alt":"André a cavalo, visto de costas, seguido por seu red heeler em uma trilha no cerrado."},{"url":"/images/montado.webp","caption":"O cerrado, a cavalo.","alt":"André de chapéu preto montando um cavalo castanho, com um cachorro ao lado e o cerrado ao fundo."}]',null,null,null,null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('4e7b1727-0220-5a5a-ae22-18a1c85920de','tornado','story','Tornado','Um companheiro de muitas histórias.','Roça','<p>Os cavalos e o cerrado fazem parte do caminho até aqui.</p>','published',now(),'[{"url":"/images/tornado.webp","caption":"Tornado em Angueretá.","alt":"Tornado selado, com rédeas vermelhas, diante da paisagem do cerrado de Angueretá."},{"url":"/images/montado.webp","caption":"Cavalgar e colecionar histórias.","alt":"André de chapéu preto montando um cavalo castanho, com um cachorro ao lado e o cerrado ao fundo."}]',null,null,null,null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('94632322-b42d-5e8d-a099-3b3c2c947b7d','fora-da-tela','story','Fora da tela','Alguns registros de quem vive a história.','Vida','<p>Há muita vida entre uma interface e outra.</p>','published',now(),'[{"url":"/images/andre-chapeu.jpeg","caption":"Um retrato no caminho.","alt":"Retrato de André com chapéu preto em um caminho ao ar livre."},{"url":"/images/caminho-cerrado.jpeg","caption":"Uma parte de mim sempre volta.","alt":"André a cavalo, visto de costas, seguido por seu red heeler em uma trilha no cerrado."}]',null,null,null,null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('08703a7d-c933-5fcc-a83c-60fe02aec3d9','2008','moment','Antes do primeiro emprego.','Estudos em desenvolvimento web','Vida','<p>Comecei a estudar desenvolvimento web em 2008. Virava a noite entre padrões web, HTML, CSS e JavaScript. Precisava trabalhar, mas as oportunidades por ali eram poucas.</p><p>Minha vida estava naquela cidade: os amigos, a bicicleta, o hardcore. Conseguir o primeiro emprego acabaria me levando para longe de tudo isso.</p>','published',now(),'[]','2008','Ipatinga · Minas Gerais','O começo',null,'A oportunidade veio de Uberlândia.','dez-anos-atras-eu-morava-em-ipatinga');
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('f2e9249a-6585-5f2b-abea-e778fd044748','2009','moment','Aprender trabalhando.','Junho de 2009 — setembro de 2010','Vida','<p>Na Webroom, transformava layouts em PSD em páginas com HTML e CSS. O que eu estudava durante a madrugada passou a fazer parte do trabalho de todos os dias.</p><p>Fui para Uberlândia e, mais tarde, levei minha mãe. Fazer um site funcionar nos diferentes navegadores exigia paciência. Foi nesse cenário que aprendi meu ofício.</p>','published',now(),'[]','2009','Uberlândia · Minas Gerais','Webroom Soluções Interativas',null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('fbb61eea-4a46-5729-a243-2ffa5883c895','2010','moment','Outra cidade. Novos trabalhos.','Setembro de 2010 — abril de 2011','Vida','<p>Na Commquest, segui como programador de interface. Convertia os desenhos em páginas, cuidava da compatibilidade entre navegadores e acompanhava os ajustes e a manutenção dos sites.</p><p>Belo Horizonte se tornou o lugar das próximas experiências em agências. A vontade de encontrar outras formas de viver continuava comigo.</p>','published',now(),'[]','2010','Belo Horizonte · Minas Gerais','Commquest Comunicação',null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('63e4a774-cffc-5184-aca6-4aa26afaa65f','2011','moment','Entre o desenho e o código.','Abril de 2011 — agosto de 2012','Vida','<p>Na Lápis Raro, trabalhei com HTML5, CSS, JavaScript e jQuery. Também entravam os temas de WordPress e a colaboração com os designers para levar as ideias dos layouts para o navegador.</p><p>Traduzir uma proposta visual em uma interface é uma parte da profissão que atravessa minha história. As ferramentas mudam; o encontro entre design e desenvolvimento continua me interessando.</p>','published',now(),'[]','2011','Belo Horizonte · Minas Gerais','Lápis Raro',null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('7bf63ec6-572a-5e4a-a856-214afca07461','2012','moment','Projetos que ampliaram o caminho.','Agosto de 2012 — fevereiro de 2015','Vida','<p>Na 3bits, participei de projetos para marcas como Coca-Cola Brasil e BDMG. Desenvolvia sites com jQuery e WordPress, usava Sass e Git e trabalhava perto da equipe criativa.</p><p>Eu gostava da profissão, mas queria uma vida que também acontecesse fora da rotina de casa e trabalho. A vontade de sair da cidade grande foi ganhando espaço.</p>','published',now(),'[]','2012','Belo Horizonte · Minas Gerais','3bits Estúdio Criativo',null,null,null);
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('04bd0432-8a57-5bdd-a2e0-9a89c68c80be','2015','moment','A vida foi para outro lugar.','Fevereiro de 2015 — março de 2023','Vida','<p>Comecei a atuar como freelancer. Vieram projetos com WordPress, Vue, Nuxt e React. Esse trabalho atravessou os anos seguintes, inclusive a fase em que passei a viver na roça.</p><p>Em Angueretá, eu tirava leite, fazia queijo, criava galinhas, capinava e aprendia habilidades braçais. Os cavalos, os cachorros, o rio e a terra vermelha passaram a fazer parte dos meus dias.</p><p>Aprendi com o corpo inteiro. Também encontrei pessoas que se tornaram família. Aquele lugar continua me chamando pela memória.</p>','published',now(),'[]','2015','Trabalho remoto · Angueretá','Freelancer',null,'Eu não nasci sertanejo, fui forjado.','um-ano-e-meio-de-roca');
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('03dfabb9-3997-5f78-a84b-9699e2433c04','2022','moment','Voltar à linha de frente.','Maio de 2022 — março de 2023','Vida','<p>Voltei ao trabalho em equipe na Plural Systems, passando por AngularJS, React e React Native, em projetos com Azure.</p><p>Escrevi naquele ano sobre voltar ao mercado depois de sete anos afastado da rotina das empresas. O trabalho remoto trouxe algo que eu desejava desde o começo: mais liberdade para escolher onde viver.</p>','published',now(),'[]','2022','Trabalho remoto','Plural Systems',null,null,'na-linha-de-frente-retomei-minha-profissao');
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('43ae4a88-33bd-5e7b-acf7-c02398b096c5','2023','moment','Construir. E continuar escrevendo.','Dezembro de 2023 — maio de 2024','Vida','<p>No fim de 2023, comecei um trabalho temporário na Evavip. Desenvolvi o front-end da plataforma com Vue e TypeScript, construindo funcionalidades e melhorando o desempenho junto às outras áreas do produto.</p><p>No começo daquele ano, eu já tinha colocado no papel outra vontade: escrever mais. Registrar o pensamento enquanto ele muda, contar histórias com informalidade e dar espaço a um antigo desejo de escrever um livro.</p>','published',now(),'[]','2023','Trabalho remoto','Evavip',null,null,'por-um-2023-mais-textual');
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('e992bdec-efcc-598a-a2d1-63f1af27549e','2025','moment','A experiência. E as inquietações.','Março de 2025 — presente','Vida','<p>Trabalho na evolução de uma aplicação Angular de grande porte: modernização gradual, componentes compartilhados, fluxos em tempo real e cuidado com acessibilidade e manutenção.</p><p>Depois de tantas limitações no início da carreira, vejo as possibilidades atuais com vontade de experimentar. Temos recursos para explorar melhor o movimento, a interação e a rolagem.</p><p>Uma parte de mim ainda volta ao cerrado. Em “Penar”, escrevi sobre continuar voltando a Angueretá pela memória.</p>','published',now(),'[]','2025','Belo Horizonte e região · trabalho híbrido','Trade Arena',null,null,'do-caos-flash-ao-tedio-flat');
insert into public.content (id, slug, kind, title, excerpt, category, body_html, status, published_at, images, year, place, company, source_url, reflection, article_slug) values ('6d480f22-20dc-547e-a7ee-7bd96752bb30','agora','moment','A vida com Acauã.','Um momento de realização','Vida','<p>Hoje, estou com meu filho Acauã. Quando penso neste momento da minha vida, a palavra que encontro é realização.</p><p>Ao mesmo tempo, existe a incerteza sobre o futuro do front-end, a profissão que faz parte da minha vida desde 2009. Essa pergunta também pertence ao capítulo que estou vivendo.</p>','published',now(),'[]','Agora','Presença & futuro','O presente',null,'O próximo capítulo ainda está em aberto.',null);
